// Category names are open-ended. No money thresholds are assumed approved.
const PRIORITY_LEVELS=['Low','Normal','High','Critical'];
const PRIORITY_DEFAULTS={version:1,thresholds:{normal:50000,high:200000,critical:1000000},categories:{}};
let prioritySettings;try{prioritySettings=JSON.parse(localStorage.getItem('pc-priority-v1'))||structuredClone(PRIORITY_DEFAULTS)}catch{prioritySettings=structuredClone(PRIORITY_DEFAULTS)}
function validatePrioritySettings(s){const t=s?.thresholds,values=t&&['normal','high','critical'].map(k=>t[k]);if(!values||values.some(v=>v!==null&&(!Number.isFinite(v)||v<=0)))return false;const configured=values.filter(v=>v!==null);if(configured.length!==0&&configured.length!==3)return false;if(configured.length&&!(values[0]<values[1]&&values[1]<values[2]))return false;return !!s.categories&&Object.values(s.categories).every(c=>['perishable','fragile','temperatureSensitive','safetySensitive'].every(k=>typeof c[k]==='boolean')&&['safetyPriority','temperaturePriority','damagePriority'].every(k=>c[k]===undefined||['None',...PRIORITY_LEVELS].includes(c[k])))}
if(!validatePrioritySettings(prioritySettings))prioritySettings=structuredClone(PRIORITY_DEFAULTS);
function evaluatePriority(r,s=prioritySettings){const lines=Array.isArray(r.products)?r.products:[],reasons=[],missing=[];let rank=0,total=0;const raise=(level,reason)=>{if(level==='None')return;rank=Math.max(rank,PRIORITY_LEVELS.indexOf(level));reasons.push(level+': '+reason)};
const f=r.facts||{};
const impact=r.type!=='Information request'||lines.length>0||['receivingMismatch','inventoryMismatch','missingItem','wrongSku','damage','stockAdjustment','replacement','refund','liability'].some(k=>f[k]===true)||['valueMMK','affectedQuantity','affectedOrders'].some(k=>Number(f[k])>0)||r.prioritySignals?.safetyIncident||r.prioritySignals?.temperatureBreach||/refund|compensation|replacement|repacking|correct stock|stock adjustment|နစ်နာကြေး|ငွေပြန်အမ်း|စာရင်းပြင်ဆင်/i.test((r.description||'')+' '+(r.outcome||''));
if(!impact)return {level:r.priorityOverride?.level||'Low',computed:'Low',amountMMK:null,needsReview:false,reasons:['Information / clarification only; product value not required'],missing:[],override:r.priorityOverride||null};
if(!lines.length)missing.push('Product category, affected quantity and unit price');
for(const p of lines){const category=typeof p.category==='string'?p.category.trim():'',profile=Object.hasOwn(s.categories,category)?s.categories[category]:null;if(!category)missing.push('Product category');else if(!profile)missing.push('Category risk profile: '+category);const q=p.affectedQuantity,price=p.unitPriceMMK;if(typeof q!=='number'||!Number.isFinite(q)||q<0||typeof price!=='number'||!Number.isFinite(price)||price<0)missing.push('Valid affected quantity / unit price');else total+=q*price;
if(profile){if((profile.safetySensitive||profile.perishable)&&r.prioritySignals?.safetyIncident)raise(profile.safetyPriority||'Critical','Safety incident affecting '+category);if(profile.temperatureSensitive&&r.prioritySignals?.temperatureBreach)raise(profile.temperaturePriority||'Critical','Temperature breach affecting '+category);if((profile.fragile||profile.perishable||profile.temperatureSensitive||profile.safetySensitive)&&(r.type==='Warehouse damage'||r.facts?.damage||r.facts?.missingItem||r.facts?.wrongSku||r.type==='Wrong / Missing item'))raise(profile.damagePriority||'High','Sensitive category with damage / missing / wrong item: '+category)}}
if(!Number.isFinite(total))missing.push('Affected value exceeds supported numeric range');
const t=s.thresholds;if(['normal','high','critical'].some(k=>t[k]===null))missing.push('MMK thresholds');else if(Number.isFinite(total)&&lines.length){if(total>=t.critical)raise('Critical','Affected value reaches Critical threshold');else if(total>=t.high)raise('High','Affected value reaches High threshold');else if(total>=t.normal)raise('Normal','Affected value reaches Normal threshold');else reasons.push('Affected value below Normal threshold')}
const computed=PRIORITY_LEVELS[rank],override=r.priorityOverride;const level=override&&PRIORITY_LEVELS.includes(override.level)?override.level:missing.length&&rank===0?null:computed;
return {level,computed,amountMMK:lines.length&& !missing.some(x=>/quantity|numeric/.test(x))?total:null,needsReview:missing.length>0,reasons,missing:[...new Set(missing)],override:override||null};}
function priorityBadge(r){const p=evaluatePriority(r),colors={Critical:'#b91c1c',High:'#c2410c',Normal:'#1d4ed8',Low:'#475569'};return `<span class="pill" style="color:${colors[p.level]||'#92400e'}">${esc(p.level||'Priority pending')}${p.needsReview?' · Manager check':''}</span>`}
